namespace ghidra.app.cmd.refs;

using ghidra.framework.cmd;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;

/**
 * Command for removing external references.
 */
public class RemoveExternalRefCmd : Command<Program> {

	private Address fromAddr;
	private int opIndex;

	/**
	 * Constructs a new command for removing an external reference.
	 * @param fromAddr the address of the codeunit making the external reference.
	 * @param opIndex the operand index.
	 */
	public RemoveExternalRefCmd(Address fromAddr, int opIndex) {
		this.fromAddr = fromAddr;
		this.opIndex = opIndex;
	}

	/* @Override */
	public bool applyTo(Program program) {
		ReferenceManager refMgr = program.getReferenceManager();

		Reference[] refs = refMgr.getReferencesFrom(fromAddr, opIndex);
		foreach (Reference @ref in refs) {
			if (@ref.isExternalReference()) {
				refMgr.delete(@ref);
			}
		}

		return true;
	}

	/* @Override */
	public string getStatusMsg() {
		return null;
	}

	/* @Override */
	public string getName() {
		return "Remove External Reference";
	}

}
